### Step 2: List the numbers and their proper divisors

Let’s list the numbers and their proper divisors:

- 1: no proper divisors
- 2: {1}
- 3: {1}
- 4: {1, 2}
- 5: {1}
- 6: {1, 2, 3}

def count_valid_permutations():
    numbers = [1, 2, 3, 4, 5, 6]
    divisors = {
        1: set(),
        2: {1},
        3: {1},
        4: {1, 2},
        5: {1},
        6: {1, 2, 3}
    }

@lru_cache(maxsize=None)
    def f(mask):
        if mask == 0:
            return 1
        count = 0
        for i in range(6):
            if (mask & (1 << i)) == 0:
                continue
            num = numbers[i]
            if all((mask & (1 << j)) != 0 for j in divisors[num]):
                count += f(mask ^ (1 << i))
        return count

